components.css:
.ds-btn-primary { height: 36px; padding: 0 14px; border: 1px solid var(--accent-strong, #c24a1a); border-radius: var(--radius-control, 6px); background: var(--accent-strong, #c24a1a); color: #ffffff; font: 500 13px/1 'Archivo', system-ui, sans-serif; cursor: pointer; }
.ds-btn-primary:hover { background: var(--accent-ink, #a63d16); border-color: var(--accent-ink, #a63d16); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--accent, #d95d2b); outline-offset: 2px; }

.ds-btn { height: 36px; padding: 0 14px; border: 1px solid var(--control, #d1ccc2); border-radius: var(--radius-control, 6px); background: var(--surface, #ffffff); color: var(--text, #2a2320); font: 500 13px/1 'Archivo', system-ui, sans-serif; cursor: pointer; }
.ds-btn:hover { background: var(--raised, #faf9f6); }
.ds-btn:focus-visible { outline: 2px solid var(--accent, #d95d2b); outline-offset: 2px; }
.ds-btn-small { height: 28px; padding: 0 10px; font-size: 12px; }

.ds-stamp { display: inline-block; font: 600 13px/1.2 'Barlow Condensed', 'Archivo', sans-serif; text-transform: uppercase; letter-spacing: 0.12em; color: var(--accent-ink, #a63d16); border: 2px solid var(--accent, #d95d2b); border-radius: var(--radius-chip, 4px); padding: 1px 8px 0; transform: rotate(-2deg); }
.ds-stamp-no { color: var(--negative-ink, #832a17); border-color: var(--negative-ink, #832a17); transform: rotate(2deg); }
.ds-stamp-landing { animation: ds-stamp-land 260ms cubic-bezier(0.2, 0.9, 0.25, 1); }
@keyframes ds-stamp-land { from { transform: rotate(-2deg) scale(1.35); opacity: 0; } to { transform: rotate(-2deg) scale(1); opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .ds-stamp-landing { animation: none; } }

.ds-pill { display: inline-block; font: 500 11.5px/1.2 'Archivo', system-ui, sans-serif; padding: 3px 9px; border-radius: 999px; white-space: nowrap; }
.ds-pill-ok { background: var(--positive-bg, #e4ede0); color: var(--positive-ink, #2f4526); }
.ds-pill-pendiente { background: var(--warning-bg, #f5edd5); color: var(--warning-ink, #6b551b); }
.ds-pill-incidencia { background: var(--negative-bg, #f7e3dc); color: var(--negative-ink, #832a17); }

.ds-kpi-strip { display: grid; grid-template-columns: repeat(4, 1fr); border: 1px solid var(--border, #eae7e0); border-radius: var(--radius-card, 8px); font-family: 'Archivo', system-ui, sans-serif; }
.ds-kpi { padding: 14px 18px; border-left: 1px solid var(--rule, #f1eee7); }
.ds-kpi:first-child { border-left: none; }
.ds-kpi-label { font-size: 14px; color: var(--muted, #6c645c); }
.ds-kpi-value { font: 600 26px/1.15 'Barlow Condensed', 'Archivo', sans-serif; font-variant-numeric: tabular-nums; margin-top: 2px; }
.ds-kpi-value.ds-accent { color: var(--accent-ink, #a63d16); }
.ds-kpi-unit { font: 500 15px 'Barlow Condensed', 'Archivo', sans-serif; color: var(--muted, #6c645c); margin-left: 4px; }
.ds-kpi-note { font-size: 12px; color: var(--muted, #6c645c); margin-top: 3px; }

.ds-table { width: 100%; border-collapse: collapse; font-family: 'Archivo', system-ui, sans-serif; color: var(--text, #2a2320); }
.ds-table th { font-size: 12px; font-weight: 400; color: var(--muted, #6c645c); text-align: left; padding: 8px 12px; }
.ds-table td { padding: 10px 12px; border-top: 1px solid var(--rule, #f1eee7); height: 44px; vertical-align: middle; font-size: 14px; }
.ds-table tr.ds-course-start td { border-top: 1px solid var(--rule-course, #ddd8ce); }
.ds-table tbody tr:hover td { background: var(--raised, #faf9f6); }
.ds-col-num { text-align: right; width: 84px; font: 600 15px 'Barlow Condensed', 'Archivo', sans-serif; font-variant-numeric: tabular-nums; }
.ds-code { font: 600 15px 'Barlow Condensed', 'Archivo', sans-serif; font-variant-numeric: tabular-nums; letter-spacing: 0.02em; white-space: nowrap; }
.ds-identity { font-weight: 500; max-width: 190px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-stamp { display: inline-block; font: 600 13px/1.2 'Barlow Condensed', 'Archivo', sans-serif; text-transform: uppercase; letter-spacing: 0.12em; color: var(--accent-ink, #a63d16); border: 2px solid var(--accent, #d95d2b); border-radius: 4px; padding: 1px 8px 0; transform: rotate(-2deg); }
.ds-stamp-no { color: var(--negative-ink, #832a17); border-color: var(--negative-ink, #832a17); transform: rotate(2deg); }
.ds-pill { display: inline-block; font: 500 11.5px/1.2 'Archivo', system-ui, sans-serif; padding: 3px 9px; border-radius: 999px; white-space: nowrap; }
.ds-pill-pendiente { background: var(--warning-bg, #f5edd5); color: var(--warning-ink, #6b551b); }
.ds-pill-ok { background: var(--positive-bg, #e4ede0); color: var(--positive-ink, #2f4526); }

.ds-field { height: 32px; border: 1px solid var(--control, #d1ccc2); border-radius: var(--radius-control, 6px); background: var(--surface, #ffffff); padding: 0 12px; font: 400 13px 'Archivo', system-ui, sans-serif; color: var(--text, #2a2320); }
.ds-field::placeholder { color: var(--muted, #6c645c); }
.ds-field:focus-visible { outline: 2px solid var(--accent, #d95d2b); outline-offset: 2px; }

.ds-rail-block { font-family: 'Archivo', system-ui, sans-serif; color: var(--text, #2a2320); }
.ds-rail-head { margin: 0 0 8px; font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
.ds-rail-card { border: 1px solid var(--border, #eae7e0); border-radius: var(--radius-card, 8px); padding: 16px; }
.ds-split-bar { display: flex; height: 10px; border-radius: 999px; overflow: hidden; margin-bottom: 12px; }
.ds-split-bar .ds-known { background: #8c8378; }
.ds-split-bar .ds-unknown { background: var(--accent, #d95d2b); }
.ds-split-figures { display: flex; justify-content: space-between; gap: 12px; }
.ds-split-label { font-size: 13px; font-weight: 500; }
.ds-figure { display: block; font: 600 21px 'Barlow Condensed', 'Archivo', sans-serif; font-variant-numeric: tabular-nums; }
.ds-figure-accent { color: var(--accent-ink, #a63d16); }
.ds-split-caption { font-size: 12px; color: var(--muted, #6c645c); margin-top: 2px; }
